525	            else if (col_then_fixed && col_else_fixed)
526	                conditional(FixedStringSource(*col_then_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
527	            else if (col_then_fixed && col_else_const_fixed)
528	                conditional(FixedStringSource(*col_then_fixed), ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
529	            else if (col_then_const_fixed && col_else_fixed)
530	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
531	            else if (col_then_const_fixed && col_else_const_fixed)
532	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed),
533	                            ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
