543	    static ColumnPtr executeGenericArray(const ColumnUInt8 * cond_col, const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type)
544	    {
545	        /// For generic implementation, arrays must be of same type.
546	        if (!arguments[1].type->equals(*arguments[2].type))
547	            return nullptr;
548	
549	        const IColumn * col_then_untyped = arguments[1].column.get();
550	        const IColumn * col_else_untyped = arguments[2].column.get();
551	
552	        const ColumnArray * col_arr_then = checkAndGetColumn<ColumnArray>(col_then_untyped);
553	        const ColumnArray * col_arr_else = checkAndGetColumn<ColumnArray>(col_else_untyped);
554	        const ColumnConst * col_arr_then_const = checkAndGetColumnConst<ColumnArray>(col_then_untyped);
555	        const ColumnConst * col_arr_else_const = checkAndGetColumnConst<ColumnArray>(col_else_untyped);
556	
557	        const PaddedPODArray<UInt8> & cond_data = cond_col->getData();
558	        size_t rows = cond_data.size();
559	
560	        if ((col_arr_then || col_arr_then_const)
561	            && (col_arr_else || col_arr_else_const))
562	        {
563	            auto res = result_type->createColumn();
564	            auto * col_res = assert_cast<ColumnArray *>(res.get());
565	
566	            if (col_arr_then && col_arr_else)
567	                conditional(GenericArraySource(*col_arr_then), GenericArraySource(*col_arr_else), GenericArraySink(col_res->getData(), col_res->getOffsets(), rows), cond_data);
568	            else if (col_arr_then && col_arr_else_const)
569	                conditional(GenericArraySource(*col_arr_then), ConstSource<GenericArraySource>(*col_arr_else_const), GenericArraySink(col_res->getData(), col_res->getOffsets(), rows), cond_data);
570	            else if (col_arr_then_const && col_arr_else)
571	                conditional(ConstSource<GenericArraySource>(*col_arr_then_const), GenericArraySource(*col_arr_else), GenericArraySink(col_res->getData(), col_res->getOffsets(), rows), cond_data);
572	            else if (col_arr_then_const && col_arr_else_const)
573	                conditional(ConstSource<GenericArraySource>(*col_arr_then_const), ConstSource<GenericArraySource>(*col_arr_else_const), GenericArraySink(col_res->getData(), col_res->getOffsets(), rows), cond_data);
574	            else
575	                return nullptr;
576	
577	            return res;
578	        }
579	
580	        return nullptr;
581	    }
