583	    ColumnPtr executeTuple(const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t input_rows_count) const
584	    {
585	        /// Calculate function for each corresponding elements of tuples.
586	
587	        const ColumnWithTypeAndName & arg1 = arguments[1];
588	        const ColumnWithTypeAndName & arg2 = arguments[2];
589	
590	        Columns col1_contents;
591	        Columns col2_contents;
592	
593	        if (const ColumnTuple * tuple1 = typeid_cast<const ColumnTuple *>(arg1.column.get()))
594	            col1_contents = tuple1->getColumnsCopy();
595	        else if (const ColumnConst * const_tuple = checkAndGetColumnConst<ColumnTuple>(arg1.column.get()))
596	            col1_contents = convertConstTupleToConstantElements(*const_tuple);
597	        else
598	            return nullptr;
599	
600	        if (const ColumnTuple * tuple2 = typeid_cast<const ColumnTuple *>(arg2.column.get()))
601	            col2_contents = tuple2->getColumnsCopy();
602	        else if (const ColumnConst * const_tuple = checkAndGetColumnConst<ColumnTuple>(arg2.column.get()))
603	            col2_contents = convertConstTupleToConstantElements(*const_tuple);
604	        else
605	            return nullptr;
606	
607	        const DataTypeTuple & type1 = static_cast<const DataTypeTuple &>(*arg1.type);
608	        const DataTypeTuple & type2 = static_cast<const DataTypeTuple &>(*arg2.type);
609	        const DataTypeTuple & tuple_result = static_cast<const DataTypeTuple &>(*result_type);
610	
611	        ColumnsWithTypeAndName temporary_columns(3);
612	        temporary_columns[0] = arguments[0];
613	
614	        size_t tuple_size = type1.getElements().size();
615	        Columns tuple_columns(tuple_size);
616	
617	        for (size_t i = 0; i < tuple_size; ++i)
618	        {
619	            temporary_columns[1] = {col1_contents[i], type1.getElements()[i], {}};
620	            temporary_columns[2] = {col2_contents[i], type2.getElements()[i], {}};
621	
622	            tuple_columns[i] = executeImpl(temporary_columns, tuple_result.getElements()[i], input_rows_count);
623	        }
624	
625	        return ColumnTuple::create(tuple_columns);
626	    }
