628	    static ColumnPtr executeGeneric(
629	        const ColumnUInt8 * cond_col, const ColumnsWithTypeAndName & arguments, size_t input_rows_count)
630	    {
631	        /// Convert both columns to the common type (if needed).
632	        const ColumnWithTypeAndName & arg1 = arguments[1];
633	        const ColumnWithTypeAndName & arg2 = arguments[2];
634	
635	        DataTypePtr common_type = getLeastSupertype(DataTypes{arg1.type, arg2.type});
636	
637	        ColumnPtr col_then = castColumn(arg1, common_type);
638	        ColumnPtr col_else = castColumn(arg2, common_type);
639	
640	        MutableColumnPtr result_column = common_type->createColumn();
641	        result_column->reserve(input_rows_count);
642	
643	        bool then_is_const = isColumnConst(*col_then);
644	        bool else_is_const = isColumnConst(*col_else);
645	
646	        bool then_is_short = col_then->size() < cond_col->size();
647	        bool else_is_short = col_else->size() < cond_col->size();
648	
649	        const auto & cond_array = cond_col->getData();
650	
651	        if (then_is_const && else_is_const)
652	        {
653	            const IColumn & then_nested_column = assert_cast<const ColumnConst &>(*col_then).getDataColumn();
654	            const IColumn & else_nested_column = assert_cast<const ColumnConst &>(*col_else).getDataColumn();
655	
656	            for (size_t i = 0; i < input_rows_count; ++i)
657	            {
658	                if (cond_array[i])
659	                    result_column->insertFrom(then_nested_column, 0);
660	                else
661	                    result_column->insertFrom(else_nested_column, 0);
662	            }
663	        }
664	        else if (then_is_const)
665	        {
666	            const IColumn & then_nested_column = assert_cast<const ColumnConst &>(*col_then).getDataColumn();
667	
668	            size_t else_index = 0;
669	            for (size_t i = 0; i < input_rows_count; ++i)
670	            {
671	                if (cond_array[i])
672	                    result_column->insertFrom(then_nested_column, 0);
673	                else
674	                    result_column->insertFrom(*col_else, else_is_short ? else_index++ : i);
675	            }
676	        }
677	        else if (else_is_const)
678	        {
679	            const IColumn & else_nested_column = assert_cast<const ColumnConst &>(*col_else).getDataColumn();
680	
681	            size_t then_index = 0;
682	            for (size_t i = 0; i < input_rows_count; ++i)
683	            {
684	                if (cond_array[i])
685	                    result_column->insertFrom(*col_then, then_is_short ? then_index++ : i);
686	                else
687	                    result_column->insertFrom(else_nested_column, 0);
688	            }
689	        }
690	        else
691	        {
692	            size_t then_index = 0, else_index = 0;
693	            for (size_t i = 0; i < input_rows_count; ++i)
694	            {
695	                if (cond_array[i])
696	                    result_column->insertFrom(*col_then, then_is_short ? then_index++ : i);
697	                else
698	                    result_column->insertFrom(*col_else, else_is_short ? else_index++ : i);
699	            }
700	        }
701	
702	        return result_column;
703	    }
