705	    ColumnPtr executeForConstAndNullableCondition(
706	        const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t /*input_rows_count*/) const
707	    {
708	        const ColumnWithTypeAndName & arg_cond = arguments[0];
709	        bool cond_is_null = arg_cond.column->onlyNull();
710	
711	        ColumnPtr not_const_condition = arg_cond.column;
712	        bool cond_is_const = false;
713	        bool cond_is_true = false;
714	        bool cond_is_false = false;
715	        if (const auto * const_arg = checkAndGetColumn<ColumnConst>(*arg_cond.column))
716	        {
717	            cond_is_const = true;
718	            not_const_condition = const_arg->getDataColumnPtr();
719	            ColumnPtr data_column = const_arg->getDataColumnPtr();
720	            if (const auto * const_nullable_arg = checkAndGetColumn<ColumnNullable>(*data_column))
721	            {
722	                data_column = const_nullable_arg->getNestedColumnPtr();
723	                if (!data_column->empty())
724	                    cond_is_null = const_nullable_arg->getNullMapData()[0];
725	            }
726	
727	            if (!data_column->empty())
728	            {
729	                cond_is_true = !cond_is_null && checkAndGetColumn<ColumnUInt8>(*data_column)->getBool(0);
730	                cond_is_false = !cond_is_null && !cond_is_true;
731	            }
732	        }
733	
734	        const auto & column1 = arguments[1];
735	        const auto & column2 = arguments[2];
736	
737	        if (cond_is_true)
738	            return castColumn(column1, result_type);
739	        else if (cond_is_false || cond_is_null)
740	            return castColumn(column2, result_type);
741	
742	        if (const auto * nullable = checkAndGetColumn<ColumnNullable>(*not_const_condition))
743	        {
744	            ColumnPtr new_cond_column = nullable->getNestedColumnPtr();
745	            size_t column_size = arg_cond.column->size();
746	
747	            if (checkAndGetColumn<ColumnUInt8>(*new_cond_column))
748	            {
749	                auto nested_column_copy = new_cond_column->cloneResized(new_cond_column->size());
750	                typeid_cast<ColumnUInt8 *>(nested_column_copy.get())->applyZeroMap(nullable->getNullMapData());
751	                new_cond_column = std::move(nested_column_copy);
752	
753	                if (cond_is_const)
754	                    new_cond_column = ColumnConst::create(new_cond_column, column_size);
755	            }
756	            else
757	                throw Exception("Illegal column " + arg_cond.column->getName() + " of " + getName() + " condition",
758	                                ErrorCodes::ILLEGAL_COLUMN);
759	
760	            ColumnsWithTypeAndName temporary_columns
761	            {
762	                { new_cond_column, removeNullable(arg_cond.type), arg_cond.name },
763	                column1,
764	                column2,
765	            };
766	
767	            return executeImpl(temporary_columns, result_type, new_cond_column->size());
768	        }
769	
770	        return nullptr;
771	    }
