789	    /// Return nested column recursively removing Nullable, examples:
790	    /// Nullable(size = 1, Int32(size = 1), UInt8(size = 1)) -> Int32(size = 1)
791	    /// Const(size = 0, Nullable(size = 1, Int32(size = 1), UInt8(size = 1))) ->
792	    /// Const(size = 0, Int32(size = 1))
793	    static ColumnPtr recursiveGetNestedColumnWithoutNullable(const ColumnPtr & column)
794	    {
795	        if (const auto * nullable = checkAndGetColumn<ColumnNullable>(*column))
796	        {
797	            /// Nullable cannot contain Nullable
798	            return nullable->getNestedColumnPtr();
799	        }
800	        else if (const auto * column_const = checkAndGetColumn<ColumnConst>(*column))
801	        {
802	            /// Save Constant, but remove Nullable
803	            return ColumnConst::create(recursiveGetNestedColumnWithoutNullable(column_const->getDataColumnPtr()), column->size());
804	        }
805	
806	        return column;
807	    }
