809	    ColumnPtr executeForNullableThenElse(const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t input_rows_count) const
810	    {
811	        const ColumnWithTypeAndName & arg_cond = arguments[0];
812	        const ColumnWithTypeAndName & arg_then = arguments[1];
813	        const ColumnWithTypeAndName & arg_else = arguments[2];
814	
815	        const auto * then_is_nullable = checkAndGetColumn<ColumnNullable>(*arg_then.column);
816	        const auto * else_is_nullable = checkAndGetColumn<ColumnNullable>(*arg_else.column);
817	
818	        if (!then_is_nullable && !else_is_nullable)
819	            return nullptr;
820	
821	        /** Calculate null mask of result and nested column separately.
822	          */
823	        ColumnPtr result_null_mask;
824	
825	        {
826	            ColumnsWithTypeAndName temporary_columns(
827	            {
828	                arg_cond,
829	                {
830	                    then_is_nullable
831	                        ? then_is_nullable->getNullMapColumnPtr()
832	                        : DataTypeUInt8().createColumnConstWithDefaultValue(input_rows_count),
833	                    std::make_shared<DataTypeUInt8>(),
834	                    ""
835	                },
836	                {
837	                    else_is_nullable
838	                        ? else_is_nullable->getNullMapColumnPtr()
839	                        : DataTypeUInt8().createColumnConstWithDefaultValue(input_rows_count),
840	                    std::make_shared<DataTypeUInt8>(),
841	                    ""
842	                }
843	            });
844	
845	            result_null_mask = executeImpl(temporary_columns, std::make_shared<DataTypeUInt8>(), input_rows_count);
846	        }
847	
848	        ColumnPtr result_nested_column;
849	
850	        {
851	            ColumnsWithTypeAndName temporary_columns(
852	            {
853	                arg_cond,
854	                {
855	                    recursiveGetNestedColumnWithoutNullable(arg_then.column),
856	                    removeNullable(arg_then.type),
857	                    ""
858	                },
859	                {
860	                    recursiveGetNestedColumnWithoutNullable(arg_else.column),
861	                    removeNullable(arg_else.type),
862	                    ""
863	                }
864	            });
865	
866	            result_nested_column = executeImpl(temporary_columns, removeNullable(result_type), temporary_columns.front().column->size());
867	        }
868	
869	        return ColumnNullable::create(
870	            materializeColumnIfConst(result_nested_column), materializeColumnIfConst(result_null_mask));
871	    }
