873	    ColumnPtr executeForNullThenElse(const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t input_rows_count) const
874	    {
875	        const ColumnWithTypeAndName & arg_cond = arguments[0];
876	        const ColumnWithTypeAndName & arg_then = arguments[1];
877	        const ColumnWithTypeAndName & arg_else = arguments[2];
878	
879	        bool then_is_null = arg_then.column->onlyNull();
880	        bool else_is_null = arg_else.column->onlyNull();
881	
882	        if (!then_is_null && !else_is_null)
883	            return nullptr;
884	
885	        if (then_is_null && else_is_null)
886	            return result_type->createColumnConstWithDefaultValue(input_rows_count);
887	
888	        bool then_is_short = arg_then.column->size() < arg_cond.column->size();
889	        bool else_is_short = arg_else.column->size() < arg_cond.column->size();
890	
891	        const ColumnUInt8 * cond_col = typeid_cast<const ColumnUInt8 *>(arg_cond.column.get());
892	        const ColumnConst * cond_const_col = checkAndGetColumnConst<ColumnVector<UInt8>>(arg_cond.column.get());
893	
894	        /// If then is NULL, we create Nullable column with null mask OR-ed with condition.
895	        if (then_is_null)
896	        {
897	            ColumnPtr arg_else_column;
898	            /// In case when arg_else column type differs with result
899	            /// column type we should cast it to result type.
900	            if (removeNullable(arg_else.type)->getName() != removeNullable(result_type)->getName())
901	                arg_else_column = castColumn(arg_else, result_type);
902	            else
903	                arg_else_column = arg_else.column;
904	
905	            if (cond_col)
906	            {
907	                auto result_column = IColumn::mutate(std::move(arg_else_column));
908	                if (else_is_short)
909	                    result_column->expand(cond_col->getData(), true);
910	                if (isColumnNullable(*result_column))
911	                {
912	                    assert_cast<ColumnNullable &>(*result_column).applyNullMap(assert_cast<const ColumnUInt8 &>(*arg_cond.column));
913	                    return result_column;
914	                }
915	                else
916	                    return ColumnNullable::create(materializeColumnIfConst(result_column), arg_cond.column);
917	            }
918	            else if (cond_const_col)
919	            {
920	                if (cond_const_col->getValue<UInt8>())
921	                    return result_type->createColumn()->cloneResized(input_rows_count);
922	                else
923	                    return makeNullableColumnIfNot(arg_else_column);
924	            }
925	            else
926	                throw Exception("Illegal column " + arg_cond.column->getName() + " of first argument of function " + getName()
927	                    + ". Must be ColumnUInt8 or ColumnConstUInt8.",
928	                    ErrorCodes::ILLEGAL_COLUMN);
929	        }
930	
931	        /// If else is NULL, we create Nullable column with null mask OR-ed with negated condition.
932	        if (else_is_null)
933	        {
934	            ColumnPtr arg_then_column;
935	            /// In case when arg_then column type differs with result
936	            /// column type we should cast it to result type.
937	            if (removeNullable(arg_then.type)->getName() != removeNullable(result_type)->getName())
938	                arg_then_column = castColumn(arg_then, result_type);
939	            else
940	                arg_then_column = arg_then.column;
941	
942	            if (cond_col)
943	            {
944	                auto result_column = IColumn::mutate(std::move(arg_then_column));
945	                if (then_is_short)
946	                    result_column->expand(cond_col->getData(), false);
947	
948	                if (isColumnNullable(*result_column))
949	                {
950	                    assert_cast<ColumnNullable &>(*result_column).applyNegatedNullMap(assert_cast<const ColumnUInt8 &>(*arg_cond.column));
951	                    return result_column;
952	                }
953	                else
954	                {
955	                    size_t size = input_rows_count;
956	                    const auto & null_map_data = cond_col->getData();
957	
958	                    auto negated_null_map = ColumnUInt8::create();
959	                    auto & negated_null_map_data = negated_null_map->getData();
960	                    negated_null_map_data.resize(size);
961	
962	                    for (size_t i = 0; i < size; ++i)
963	                        negated_null_map_data[i] = !null_map_data[i];
964	
965	                    return ColumnNullable::create(materializeColumnIfConst(result_column), std::move(negated_null_map));
966	                }
967	            }
968	            else if (cond_const_col)
969	            {
970	                if (cond_const_col->getValue<UInt8>())
971	                    return makeNullableColumnIfNot(arg_then_column);
972	                else
973	                    return result_type->createColumn()->cloneResized(input_rows_count);
974	            }
975	            else
976	                throw Exception("Illegal column " + arg_cond.column->getName() + " of first argument of function " + getName()
977	                    + ". Must be ColumnUInt8 or ColumnConstUInt8.",
978	                    ErrorCodes::ILLEGAL_COLUMN);
979	        }
980	
981	        return nullptr;
982	    }
