984	    static void executeShortCircuitArguments(ColumnsWithTypeAndName & arguments)
985	    {
986	        int last_short_circuit_argument_index = checkShortCircuitArguments(arguments);
987	        if (last_short_circuit_argument_index == -1)
988	            return;
989	
990	        executeColumnIfNeeded(arguments[0]);
991	
992	        /// Check if condition is const or null to not create full mask from it.
993	        if ((isColumnConst(*arguments[0].column) || arguments[0].column->onlyNull()) && !arguments[0].column->empty())
994	        {
995	            bool value = arguments[0].column->getBool(0);
996	            executeColumnIfNeeded(arguments[1], !value);
997	            executeColumnIfNeeded(arguments[2], value);
998	            return;
999	        }
1000

1000	
1001	        IColumn::Filter mask(arguments[0].column->size(), 1);
1002	        auto mask_info = extractMask(mask, arguments[0].column);
1003	        maskedExecute(arguments[1], mask, mask_info);
1004	        inverseMask(mask, mask_info);
1005	        maskedExecute(arguments[2], mask, mask_info);
1006	    }
