1044	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & args, const DataTypePtr & result_type, size_t input_rows_count) const override
1045	    {
1046	        ColumnsWithTypeAndName arguments = args;
1047	        executeShortCircuitArguments(arguments);
1048	        ColumnPtr res;
1049	        if (   (res = executeForConstAndNullableCondition(arguments, result_type, input_rows_count))
1050	            || (res = executeForNullThenElse(arguments, result_type, input_rows_count))
1051	            || (res = executeForNullableThenElse(arguments, result_type, input_rows_count)))
1052	            return res;
1053	
1054	        const ColumnWithTypeAndName & arg_cond = arguments[0];
1055	        const ColumnWithTypeAndName & arg_then = arguments[1];
1056	        const ColumnWithTypeAndName & arg_else = arguments[2];
1057	
1058	        /// A case for identical then and else (pointers are the same).
1059	        if (arg_then.column.get() == arg_else.column.get())
1060	        {
1061	            /// Just point result to them.
1062	            return arg_then.column;
1063	        }
1064	
1065	        const ColumnUInt8 * cond_col = typeid_cast<const ColumnUInt8 *>(arg_cond.column.get());
1066	        const ColumnConst * cond_const_col = checkAndGetColumnConst<ColumnVector<UInt8>>(arg_cond.column.get());
1067	        ColumnPtr materialized_cond_col;
1068	
1069	        if (cond_const_col)
1070	        {
1071	            if (arg_then.type->equals(*arg_else.type))
1072	            {
1073	                return cond_const_col->getValue<UInt8>()
1074	                    ? arg_then.column
1075	                    : arg_else.column;
1076	            }
1077	            else
1078	            {
1079	                materialized_cond_col = cond_const_col->convertToFullColumn();
1080	                cond_col = typeid_cast<const ColumnUInt8 *>(&*materialized_cond_col);
1081	            }
1082	        }
1083	
1084	        if (!cond_col)
1085	            throw Exception("Illegal column " + arg_cond.column->getName() + " of first argument of function " + getName()
1086	                + ". Must be ColumnUInt8 or ColumnConstUInt8.",
1087	                ErrorCodes::ILLEGAL_COLUMN);
1088	
1089	        auto call = [&](const auto & types) -> bool
1090	        {
1091	            using Types = std::decay_t<decltype(types)>;
1092	            using T0 = typename Types::LeftType;
1093	            using T1 = typename Types::RightType;
1094	
1095	            res = executeTyped<T0, T1>(cond_col, arguments, result_type, input_rows_count);
1096	            return res != nullptr;
1097	        };
1098	
1099	        TypeIndex left_id = arg_then.type->getTypeId();
1100	        TypeIndex right_id = arg_else.type->getTypeId();
1101	
1102	        if (const auto * left_array = checkAndGetDataType<DataTypeArray>(arg_then.type.get()))
1103	            left_id = left_array->getNestedType()->getTypeId();
1104	
1105	        if (const auto * right_array = checkAndGetDataType<DataTypeArray>(arg_else.type.get()))
1106	            right_id = right_array->getNestedType()->getTypeId();
1107	
1108	        if (!(callOnBasicTypes<true, true, true, false>(left_id, right_id, call)
1109	            || (res = executeTyped<UUID, UUID>(cond_col, arguments, result_type, input_rows_count))
1110	            || (res = executeString(cond_col, arguments, result_type))
1111	            || (res = executeGenericArray(cond_col, arguments, result_type))
1112	            || (res = executeTuple(arguments, result_type, input_rows_count))))
1113	        {
1114	            return executeGeneric(cond_col, arguments, input_rows_count);
1115	        }
1116	
1117	        return res;
1118	    }
